SELECT i.point_id, i.cart_id, i.point_code, p.point_name, l.location_name, a.aisle_name, c.cart_code, c.status AS cart_status, i.arrive_time, i.last_task_code, COALESCE(c.current_quantity, 0) AS current_quantity, i.lock_status, i.remark, su.nickname AS updated_by_name, i.updated_time FROM wms_cart_inventory i LEFT JOIN wms_location l ON l.id = i.location_id LEFT JOIN wms_aisle a ON a.id = i.aisle_id LEFT JOIN wms_point p ON p.id = i.point_id LEFT JOIN wms_cart c ON c.id = i.cart_id LEFT JOIN sys_user su ON su.id = i.updated_by
AND i.location_id = #{query.locationId}
AND i.aisle_id = #{query.aisleId}
AND i.point_code LIKE '%' || #{query.pointCode} || '%'
AND c.cart_code LIKE '%' || #{query.cartCode} || '%'
AND i.lock_status = #{query.lockStatus}
ORDER BY i.aisle_id ASC, i.point_code ASC

SELECT i.point_id, i.point_code, p.point_name, l.location_name, a.aisle_name FROM wms_cart_inventory i JOIN wms_point p ON p.id = i.point_id LEFT JOIN wms_location l ON l.id = i.location_id LEFT JOIN wms_aisle a ON a.id = i.aisle_id WHERE i.cart_id IS NULL AND i.lock_status = 0
AND i.location_id = #{locationId}
AND i.aisle_id = #{aisleId}
ORDER BY i.aisle_id ASC, i.point_code ASC
